def evaluate_state(state_view, player_id):
    if player_id == 0:
        own = sum(state_view.board[0:6])
        opp = sum(state_view.board[6:12])
        captured = state_view.captured[0] - state_view.captured[1]
    else:
        own = sum(state_view.board[6:12])
        opp = sum(state_view.board[0:6])
        captured = state_view.captured[1] - state_view.captured[0]
    score = captured + own - 0.5 * opp
    return max(-10.0, min(10.0, float(score)))

def evaluate_state(state_view, player_id):
    if player_id == 0:
        own = sum(state_view.board[0:6])
        opp = sum(state_view.board[6:12])
        captured = state_view.captured[0] - state_view.captured[1]
    else:
        own = sum(state_view.board[6:12])
        opp = sum(state_view.board[0:6])
        captured = state_view.captured[1] - state_view.captured[0]
    if state_view.current_player == player_id:
        mobility = len(state_view.legal_actions)
        sign = 1.0
    else:
        mobility = len(state_view.legal_actions)
        sign = -1.0
    score = captured + own - opp + 0.4 * sign * mobility
    return max(-10.0, min(10.0, float(score)))

def evaluate_state(state_view, player_id):
    if player_id == 0:
        own = sum(state_view.board[0:6])
        opp = sum(state_view.board[6:12])
        captured = state_view.captured[0] - state_view.captured[1]
    else:
        own = sum(state_view.board[6:12])
        opp = sum(state_view.board[0:6])
        captured = state_view.captured[1] - state_view.captured[0]
    if state_view.current_player == player_id:
        discount = 0.25
    else:
        discount = 0.25 + 0.05 * len(state_view.legal_actions)
    score = captured + own - discount * opp
    return max(-10.0, min(10.0, float(score)))

def evaluate_state(state_view, player_id):
    if player_id == 0:
        own = sum(state_view.board[0:6])
        opp = sum(state_view.board[6:12])
        captured = state_view.captured[0] - state_view.captured[1]
    else:
        own = sum(state_view.board[6:12])
        opp = sum(state_view.board[0:6])
        captured = state_view.captured[1] - state_view.captured[0]
    seed_delta = own - opp
    compressed = seed_delta / (1.0 + 0.1 * abs(seed_delta))
    score = captured + compressed
    return max(-10.0, min(10.0, float(score)))

def evaluate_state(state_view, player_id):
    if player_id == 0:
        own = state_view.board[0] * 1 + state_view.board[1] * 2 + state_view.board[2] * 3 + state_view.board[3] * 4 + state_view.board[4] * 5 + state_view.board[5] * 6
        opp = state_view.board[6] * 1 + state_view.board[7] * 2 + state_view.board[8] * 3 + state_view.board[9] * 4 + state_view.board[10] * 5 + state_view.board[11] * 6
        captured = state_view.captured[0] - state_view.captured[1]
    else:
        own = state_view.board[6] * 1 + state_view.board[7] * 2 + state_view.board[8] * 3 + state_view.board[9] * 4 + state_view.board[10] * 5 + state_view.board[11] * 6
        opp = state_view.board[0] * 1 + state_view.board[1] * 2 + state_view.board[2] * 3 + state_view.board[3] * 4 + state_view.board[4] * 5 + state_view.board[5] * 6
        captured = state_view.captured[1] - state_view.captured[0]
    score = captured + 0.2 * (own - opp)
    return max(-10.0, min(10.0, float(score)))
